                        if type(s) == "table" and num(s.balance) > 0 then fire("PlotService", "CollectBalance", tonumber(idx)) end
                    end
                end
            end
            if on("ad_equipbest") and not S.lsBusy and now - t.eq > 10 then t.eq = now fire("PlotService", "EquipBest") end
            if d and on("ad_level") and now - t.lvl > 0.25 then
                t.lvl = now
                local byKey = {}
                for _, u in ipairs(units()) do byKey[u.key] = u end
                local bestIdx, bestCost
                for idx, s in pairs(type(d.Slots) == "table" and d.Slots or {}) do
                    local u = type(s) == "table" and byKey[s.unitId]
                    if u then
                        local c = levelCost(u)
                        if c > 0 and (not bestCost or c < bestCost) then bestIdx, bestCost = tonumber(idx), c end
                    end
                end
                if bestIdx and S.canSpend(bestCost) then fire("PlotService", "LevelUpSlot", bestIdx) end
            end
            pcall(function()
                local d2 = data()
                local cash = d2 and num(d2.Money) or 0
                local placed, earn = 0, 0
                local byKey = {}
                for _, u in ipairs(units()) do byKey[u.key] = u end
                for _, s in pairs(d2 and type(d2.Slots) == "table" and d2.Slots or {}) do
                    local u = type(s) == "table" and byKey[s.unitId]
                    if u then placed = placed + 1 earn = earn + unitIncome(u.name, u.attrs) end
                end
                plotStatus:SetText(string.format(L["Cash %s\n%d units  ·  ~%s/s"], abbrev(cash), placed, abbrev(earn)))
                local dice = d2 and d2.Dice or "?"
                local fullNow = S.fullAt and os.clock() - S.fullAt < 4
                rollStatus:SetText(string.format(L["Dice %s  ·  Rolls %d"], clip(dice, 12), S.rolls)
                    .. (fullNow and "\nInventory full, selling junk" or (S.lastRoll ~= "" and ("\nLast pull: " .. clip(S.lastRoll, 14) .. " (" .. tostring(S.lastRar or "?") .. ")") or "")))
            end)
            task.wait(0.25)
        end
    end)

    local HIGH = { "Divine", "Exotic", "Celestial", "Secret I", "Secret II", "Heavenly", "Exclusive" }
    local TOP = { "Celestial", "Secret I", "Secret II", "Heavenly", "Exclusive" }

    local Alert = Tabs.Farm:AddRightGroupbox(L["Alerts"], "eye")
    Alert:AddDropdown("ad_alertrars", { Values = RARITY_ORDER, Default = HIGH, Multi = true, AllowNull = true, Text = L["Alert Rarities"] })
    Alert:AddDropdown("ad_alertmuts", { Values = MUT_LIST, Default = { "Diamond", "Ruby", "Rainbow" }, Multi = true, AllowNull = true, Text = L["Alert Mutations"] })
    Alert:AddToggle("ad_alert", { Text = L["Popup + Sound"], Default = true })
    Alert:AddToggle("ad_alertlock", { Text = L["Lock Alerted Units"], Default = true, Tooltip = L["So they never get sold or fused."] })
    Alert:AddToggle("ad_alertstop", { Text = L["Stop Rolling On Alert"], Default = false })
    local alertStatus = Alert:AddLabel(L["Session 0m  ·  Alerts 0"], true)

    local Hook = Tabs.Settings:AddRightGroupbox(L["Discord Webhook"], "message-square")
    Hook:AddInput("ad_webhook", { Default = "", Numeric = false, Finished = true, ClearTextOnFocus = false, Text = L["Webhook URL"], Placeholder = "https://discord.com/api/webhooks/..." })
    Hook:AddInput("ad_pingid", { Default = "", Numeric = true, Finished = true, ClearTextOnFocus = false, Text = L["Ping User ID"], Placeholder = L["Optional, your Discord ID"] })
    Hook:AddDropdown("ad_hookrars", { Values = RARITY_ORDER, Default = TOP, Multi = true, AllowNull = true, Text = L["Send Rarities"] })
    Hook:AddDropdown("ad_hookmuts", { Values = MUT_LIST, Default = { "Ruby", "Rainbow" }, Multi = true, AllowNull = true, Text = L["Send Mutations"] })
    Hook:AddToggle("ad_hooksummary", { Text = L["Summary Every 30 Min"], Default = false, Tooltip = L["Rolls, alerts and cash."] })

    local httpReq = request or (syn and syn.request) or http_request
    local function validHook(url)
        return type(url) == "string" and (url:match("^https://discord%.com/api/webhooks/") or url:match("^https://discordapp%.com/api/webhooks/") or url:match("^https://ptb%.discord%.com/api/webhooks/") or url:match("^https://canary%.discord%.com/api/webhooks/")) ~= nil
    end
    local function sendHook(title, desc, color, ping)
        local url = Opt.ad_webhook and Opt.ad_webhook.Value
        if not (httpReq and validHook(url)) then return false end
        local id = tostring(Opt.ad_pingid and Opt.ad_pingid.Value or ""):gsub("%D", "")
        local body = {
            username = "COMBO_WICK",
            embeds = { { title = title, description = desc, color = color or 16766720, footer = { text = "Anime Dice  ·  " .. lp.Name } } },
        }
        if ping and id ~= "" then body.content = "<@" .. id .. ">" end
        local ok, res = pcall(httpReq, { Url = url, Method = "POST", Headers = { ["Content-Type"] = "application/json" }, Body = HttpService:JSONEncode(body) })
        return ok and type(res) == "table" and (res.StatusCode == 204 or res.StatusCode == 200)
    end
    local function sessionText()
        local mins = math.floor((os.clock() - S.startedAt) / 60)
        local h, m = math.floor(mins / 60), mins % 60
        return (h > 0 and (h .. "h " .. m .. "m") or (m .. "m"))
    end
    Hook:AddButton({ Text = L["Test Webhook"], Func = function()
        task.spawn(function()
            if not validHook(Opt.ad_webhook.Value) then notify(L["Paste a Discord webhook URL first"]) return end
            notify(sendHook(L["Webhook connected"], L["Rare pulls will show up here."], 5763719, true) and L["Webhook works"] or L["Webhook failed"])
        end)
    end })

    local function playPing()
        pcall(function()
            local s = Instance.new("Sound")
            s.SoundId = "rbxasset://sounds/electronicpingshort.wav"
            s.Volume = 1
            s.Parent = workspace.CurrentCamera or workspace
            s:Play()
            task.delay(3, function() pcall(function() s:Destroy() end) end)
        end)
    end
    local function stopRolling(why)
        if on("ad_roll") then
            pcall(function() Toggles.ad_roll:SetValue(false) end)
            notify(L["Stopped rolling: "] .. why)
        end
    end

    local seen, primed = {}, false
    task.spawn(function()
        while RUNNING do
            local list = units()
            if not primed then
                for _, u in ipairs(list) do seen[u.key] = true end
                primed = #list > 0 or data() ~= nil
            else
                local toLock = {}
                local stopSet = multiSet("ad_stopunits")
                for _, u in ipairs(list) do
                    if not seen[u.key] then
                        seen[u.key] = true
                        local mut = u.attrs.mutation and (" [" .. tostring(u.attrs.mutation) .. "]") or ""
                        local line = u.name .. mut .. " (" .. u.rarity .. ")"
                        local wanted = stopSet and stopSet[u.name]
                        if S.isAlert(u) or wanted then
                            S.rare = S.rare + 1
                            S.lastAlert = line
                            if on("ad_alert") then
                                notify((wanted and L["Target pulled! "] or L["Rare pull! "]) .. line)
                                playPing()
                            end
                            if on("ad_alertlock") and not u.locked then toLock[u.key] = true end
                            if wanted then stopRolling(u.name) elseif on("ad_alertstop") then stopRolling(line) end
                        end
                        if S.isHook(u) or wanted then
                            local chance = unitChance(u.name, u.attrs.mutation)
                            task.spawn(sendHook, wanted and "Target pulled!" or "Rare pull!", string.format("**%s**%s\nRarity: %s%s", u.name, mut, u.rarity, chance and ("\nChance: 1 in " .. abbrev(chance)) or ""), 16766720, true)
                        end
                    end
                end
                if next(toLock) then fire("UnitService", "SetLocked", toLock) end
            end
            pcall(function()
                local lines = { string.format("Session %s  ·  Alerts %d", sessionText(), S.rare) }
                if S.lastAlert then lines[#lines + 1] = "Last: " .. clip(S.lastAlert, 24) end
                alertStatus:SetText(table.concat(lines, "\n"))
            end)
            task.wait(0.4)
        end
    end)
    task.spawn(function()
        local last = os.clock()
        while RUNNING do
            if on("ad_hooksummary") and os.clock() - last >= 1800 then
                last = os.clock()
                local d = data()
                task.spawn(sendHook, "Session summary", string.format("Time: %s\nRolls: %d\nAlerts: %d\nCash: %s\nRebirth: %d",
                    sessionText(), S.rolls, S.rare, abbrev(money()), d and num(d.Rebirth) or 0), 3447003, false)
            end
            task.wait(5)
        end
    end)
end)

section(L["Units"], function()
    local function sellable(u, rar, team)
        return rar[u.rarity] == true and not keepUnit(u, team or teamSet())
    end
    local function sellNow()
        local rar = multiSet("ad_sellrar")
        if not rar then return 0 end
        local keys = {}
        local team = teamSet()
        for _, u in ipairs(units()) do
            if sellable(u, rar, team) then keys[#keys + 1] = u.key end
        end
        if #keys == 0 then return 0 end
        invoke("SellService", "SellInventory", keys)
        return #keys
    end
    local function lockNow()
        local rar = multiSet("ad_lockrar")
        if not rar then return 0 end
        local map, n = {}, 0
        for _, u in ipairs(units()) do
            if rar[u.rarity] and not u.locked then map[u.key] = true n = n + 1 end
        end
        if n > 0 then fire("UnitService", "SetLocked", map) end
        return n
    end

    local function protected(u, team)
        return keepUnit(u, team) or S.isAlert(u)
    end
    local function sellJunk()
        local team = teamSet()
        local list = {}
        for _, u in ipairs(units()) do
            if not protected(u, team) then u.inc = unitIncome(u.name, u.attrs) list[#list + 1] = u end
        end
        if #list == 0 then return 0 end
        table.sort(list, function(a, b) return a.inc < b.inc end)
        local n = math.max(5, math.floor(#list * 0.3))
        local keys = {}
        for i = 1, math.min(n, #list) do keys[#keys + 1] = list[i].key end
        invoke("SellService", "SellInventory", keys)
        return #keys
    end

    local function slotOf(key)
        local d = data()
        for idx, s in pairs(d and type(d.Slots) == "table" and d.Slots or {}) do
            if type(s) == "table" and s.unitId == key then return tonumber(idx) end
        end
    end
    local function liveLevel(key)
        local d = data()
        local e = d and type(d.Inventory) == "table" and d.Inventory[key]
        return type(e) == "table" and type(e.attributes) == "table" and num(e.attributes.level) or 1
    end
    local function workSlot()
        local d = data()
        local byKey = {}
        for _, u in ipairs(units()) do byKey[u.key] = u end
        local bestIdx, bestKey, bestInc
        for idx, s in pairs(d and type(d.Slots) == "table" and d.Slots or {}) do
            local u = type(s) == "table" and byKey[s.unitId]
            if u then
                local inc = unitIncome(u.name, u.attrs)
                if not bestInc or inc < bestInc then bestIdx, bestKey, bestInc = tonumber(idx), u.key, inc end
            end
        end
        return bestIdx, bestKey
    end
    local function levelAndSell(u)
        local slot, origKey = workSlot()
        if not slot then return false end
        S.lsBusy, S.lsKey = true, u.key
        local sold = false
        pcall(function()
            fire("PlotService", "CollectBalance", slot)
            if not invoke("UnitService", "Equip", u.key) then return end
            task.wait(0.55)
            fire("PlotService", "InteractSlot", slot)
            if not waitUntil(function() return slotOf(u.key) == slot end, 2.5) then
                invoke("UnitService", "Unequip")
                return
            end
            local baseMut = unitIncome(u.name, { mutation = u.attrs.mutation })
            local baseFull = unitIncome(u.name, { mutation = u.attrs.mutation, trait = u.attrs.trait, grade = u.attrs.grade })
            for _ = 1, 30 do
                if not (RUNNING and on("ad_levelsell")) then break end
                local lvl = liveLevel(u.key)
                local cost = math.floor(baseMut * 1.6 ^ (lvl - 1))
                if cost <= 0 or cost >= baseFull * 10 or not S.canSpend(cost) then break end
                fire("PlotService", "LevelUpSlot", slot)
                if not waitUntil(function() return liveLevel(u.key) > lvl end, 1.2) then break end
                task.wait(0.12)
            end
            task.wait(0.55)
            if origKey and invoke("UnitService", "Equip", origKey) then
                task.wait(0.55)
                fire("PlotService", "InteractSlot", slot)
                waitUntil(function() return slotOf(origKey) == slot end, 2.5)
            else
                task.wait(0.55)
                fire("PlotService", "InteractSlot", slot)
                waitUntil(function() return slotOf(u.key) == nil end, 2.5)
                task.wait(0.55)
                invoke("UnitService", "Unequip")
            end
            if slotOf(u.key) == nil then
                S.lsKey = nil
                invoke("SellService", "SellInventory", { u.key })
                S.lsCount = (S.lsCount or 0) + 1
                sold = true
            end
        end)
        S.lsBusy, S.lsKey = false, nil
        return sold
    end

    local fullRE = remote("NotificationService", "RE", "TextNotification")
    if fullRE then
        track(fullRE.OnClientEvent:Connect(function(payload)
            local msg = type(payload) == "table" and payload.message or payload
            if type(msg) == "string" and msg:lower():find("inventory is full", 1, true) then S.fullAt = os.clock() end
        end))
    end

    local Sell = Tabs.Units:AddLeftGroupbox(L["Selling"], "dollar-sign")
    Sell:AddDropdown("ad_sellrar", { Values = RARITY_ORDER, Default = {}, Multi = true, AllowNull = true, Text = L["Sell Rarities"] })
    Sell:AddToggle("ad_autosell", { Text = L["Auto Sell"], Default = false, Tooltip = L["Follows your Protection rules."] })
    Sell:AddToggle("ad_levelsell", { Text = L["Level Up Before Selling"], Default = false, Tooltip = L["Units sell for more cash. Borrows a plot slot for a moment."] })
    Sell:AddToggle("ad_selljunk", { Text = L["Sell Junk When Full"], Default = true, Tooltip = L["Frees space when your inventory fills up. Keeps protected units."] })
    local sellStatus = Sell:AddLabel("", true)
    Sell:AddButton({ Text = L["Sell Now"], Func = function()
        task.spawn(function()
            local n = sellNow()
            notify(n > 0 and (L["Sold "] .. n .. L[" units"]) or L["Nothing to sell"])
        end)
    end })

    local Lock = Tabs.Units:AddRightGroupbox(L["Protection"], "shield")
    Lock:AddDropdown("ad_lockrar", { Values = RARITY_ORDER, Default = {}, Multi = true, AllowNull = true, Text = L["Auto Lock Rarities"] })
    Lock:AddToggle("ad_autolock", { Text = L["Auto Lock"], Default = false, Tooltip = L["Locks units of these rarities."] })
    Lock:AddDivider()
    Lock:AddToggle("ad_keepgraded", { Text = L["Keep S Grade and Up"], Default = true })
    Lock:AddToggle("ad_keeptrait", { Text = L["Keep Units With Traits"], Default = true })
    Lock:AddDropdown("ad_keepmuts", { Values = MUT_LIST, Default = { "Diamond", "Ruby", "Rainbow" }, Multi = true, AllowNull = true, Text = L["Keep Mutations"], Tooltip = L["Never sold or fused."] })
    Lock:AddLabel(L["These rules apply to selling and fusing."], true)

    local Fuse = Tabs.Units:AddLeftGroupbox(L["Fusing"], "zap")
    Fuse:AddDropdown("ad_fuserar", { Values = RARITY_ORDER, Default = {}, Multi = true, AllowNull = true, Text = L["Fuse Rarities"], Tooltip = L["Units of these rarities get fused 3 at a time."] })
    Fuse:AddToggle("ad_fuse", { Text = L["Auto Fuse"], Default = false, Tooltip = L["Follows your Protection rules."] })
    local fuseStatus = Fuse:AddLabel(L["Idle"], true)

    local FZ = { count = 0, last = "", offset = 0 }
    local function fuseCandidates()
        local rar = multiSet("ad_fuserar")
        if not rar then return {} end
        local team = teamSet()
        local out = {}
        for _, u in ipairs(units()) do
            local a = u.attrs
            if rar[u.rarity] and not keepUnit(u, team) then
                local c = unitChance(u.name, a.mutation)
                if c then u.chance = c out[#out + 1] = u end
            end
        end
        table.sort(out, function(x, y) return x.chance < y.chance end)
        return out
    end
    local function fuseCost(sum) return sum * 10000 * (sum / 1e12) ^ 0.2 end
    local function fuseOnce()
        local list = fuseCandidates()
        if #list < 3 then FZ.last = "Need 3 matching units" return end
        local start = math.min(FZ.offset, #list - 3)
        local a, b, c = list[start + 1], list[start + 2], list[start + 3]
        local cost = fuseCost(a.chance + b.chance + c.chance)
        if not S.canSpend(cost) then FZ.last = "Need " .. abbrev(cost) .. " cash" return end
        if not on("ad_fuse") and not FZ.manual then return end
        FZ.manual = false
        fire("FusingService", "Fuse", a.key, b.key, c.key)
    end
    local resultRE = remote("FusingService", "RE", "Result")
    if resultRE then
        track(resultRE.OnClientEvent:Connect(function(key, err, info)
            if err then
                FZ.last = clip(err, 40)
                if tostring(err):find("balanced") then FZ.offset = FZ.offset + 1 end
            else
                FZ.count = FZ.count + 1
                FZ.offset = 0
                local nm = type(info) == "table" and (info.name or info.result) or nil
                local mut = type(info) == "table" and info.mutation or nil
                FZ.last = nm and ("Got " .. clip(nm, 14) .. " (" .. unitRarity(nm, mut) .. ")") or "Fused"
            end
        end))
    end
    Fuse:AddButton({ Text = L["Fuse Once"], Func = function() FZ.manual = true task.spawn(fuseOnce) end })
    task.spawn(function()
        local lastFuse = 0
        while RUNNING do
            if on("ad_fuse") and os.clock() - lastFuse > 3.6 then
                lastFuse = os.clock()
                pcall(fuseOnce)
            end
            pcall(function()
                local head = on("ad_fuse") and L["Fusing"] or "Off"
                fuseStatus:SetText(string.format(L["%s  ·  Fused %d  ·  %d ready"], head, FZ.count, #fuseCandidates()) .. ((on("ad_fuse") and FZ.last ~= "") and ("\n" .. FZ.last) or ""))
            end)
            task.wait(0.5)
        end
    end)

    local function placedUnits()
        local out = {}
        local d = data()
        local byKey = {}
        for _, u in ipairs(units()) do byKey[u.key] = u end
        local mode = Opt.ad_rerollmode and Opt.ad_rerollmode.Value or "Placed Units"
        local added = {}
        if mode ~= "Locked Units" then
            for idx, s in pairs(d and type(d.Slots) == "table" and d.Slots or {}) do
                local u = type(s) == "table" and byKey[s.unitId]
                if u then u.slot = tonumber(idx) out[#out + 1] = u added[u.key] = true end
            end
        end
        if mode ~= "Placed Units" then
            for _, u in pairs(byKey) do
                if u.locked and not added[u.key] then u.slot = 99 out[#out + 1] = u end
            end
        end
        table.sort(out, function(a, b) return (a.slot or 0) < (b.slot or 0) end)
        return out
    end

    local G = Tabs.Units:AddRightGroupbox(L["Rerolls"], "trending-up")
    G:AddDropdown("ad_rerollmode", { Values = { "Placed Units", "Locked Units", "Placed + Locked" }, Default = "Placed Units", Text = L["Reroll Units"] })
    G:AddDivider()
    G:AddDropdown("ad_gradetarget", { Values = GRADE_LIST, Default = GRADE_LIST[6] or GRADE_LIST[#GRADE_LIST], Text = L["Stop At Grade"], Tooltip = L["This grade or better."] })
    G:AddToggle("ad_grade", { Text = L["Auto Grade Reroll"], Default = false, Tooltip = L["Uses Gems."] })
    G:AddDivider()
    G:AddDropdown("ad_traittarget", { Values = TRAIT_LIST, Default = {}, Multi = true, AllowNull = true, Text = L["Stop At Traits"], Tooltip = L["Or anything rarer."] })
    G:AddToggle("ad_trait", { Text = L["Auto Trait Reroll"], Default = false, Tooltip = L["Uses Trait Rerolls."] })
    local rerollStatus = G:AddLabel("-", true)

    task.spawn(function()
        local lastSell, lastJunk = 0, 0
        while RUNNING do
            local now = os.clock()
            local full = S.fullAt and now - S.fullAt < 4
            if on("ad_selljunk") and full and now - lastJunk > 3 then
                lastJunk = now
                local ok, n = pcall(sellJunk)
                if ok and n and n > 0 then S.sellMsg = "Inventory full, sold " .. n .. " junk" end
            end
            if on("ad_autosell") and now - lastSell > 3 then
                lastSell = now
                local rar = multiSet("ad_sellrar")
                if rar then
                    if on("ad_levelsell") then
                        local list = {}
                        for _, u in ipairs(units()) do
                            if sellable(u, rar) then u.inc = unitIncome(u.name, u.attrs) list[#list + 1] = u end
                        end
                        table.sort(list, function(a, b) return a.inc > b.inc end)
                        if #list > 12 then
                            local keys = {}
                            for i = 13, #list do keys[#keys + 1] = list[i].key end
                            invoke("SellService", "SellInventory", keys)
                        end
                        if list[1] and not levelAndSell(list[1]) then pcall(sellNow) end
                    else
                        pcall(sellNow)
                    end
                end
            end
            pcall(function()
                local lines = {}
                if S.lsBusy then lines[#lines + 1] = "Levelling a unit to sell" end
                if (S.lsCount or 0) > 0 then lines[#lines + 1] = "Levelled & sold: " .. S.lsCount end
                if S.sellMsg then lines[#lines + 1] = S.sellMsg end
                sellStatus:SetText(table.concat(lines, "\n"))
            end)
            task.wait(0.3)
        end
    end)

    task.spawn(function()
        local t = { lock = 0, roll = 0 }
        while RUNNING do
            local now = os.clock()
            if on("ad_autolock") and now - t.lock > 3 then t.lock = now pcall(lockNow) end
            if now - t.roll > 0.3 then
                t.roll = now
                S.gradeMsg = nil
                if on("ad_grade") then
                    if itemAmount("Gems") <= 0 then
                        S.gradeMsg = "Grade: out of Gems"
                    else
                        local target = GRADE_RANK[Opt.ad_gradetarget and Opt.ad_gradetarget.Value or ""] or #GRADE_LIST
                        S.gradeMsg = "Grade: all done"
                        for _, u in ipairs(placedUnits()) do
                            if (GRADE_RANK[u.attrs.grade or ""] or 0) < target then
                                S.gradeMsg = "Grade: " .. clip(u.name, 12) .. " (" .. tostring(u.attrs.grade or "none") .. ")"
                                fire("GradeService", "Roll", u.key, true)
                                break
                            end
                        end
                    end
                end
                S.traitMsg = nil
                local want = multiSet("ad_traittarget")
                if on("ad_trait") and not want then
                    S.traitMsg = "Trait: pick traits first"
                elseif on("ad_trait") and itemAmount("Trait Reroll") <= 0 then
                    S.traitMsg = "Trait: out of rerolls"
                elseif on("ad_trait") then
                    S.traitMsg = "Trait: all done"
                    do
                        local floorRank = math.huge
                        for name in pairs(want) do floorRank = math.min(floorRank, TRAIT_RANK[name] or math.huge) end
                        for _, u in ipairs(placedUnits()) do
                            local cur = u.attrs.trait
                            if not want[cur or ""] and (TRAIT_RANK[cur or ""] or 0) < floorRank then
                                S.traitMsg = "Trait: " .. clip(u.name, 12) .. " (" .. tostring(cur or "none") .. ")"
                                fire("TraitService", "Roll", u.key, true)
                                break
                            end
                        end
                    end
                end
            end
            pcall(function()
                local lines = { "Gems " .. abbrev(itemAmount("Gems")) .. "  ·  Trait Rerolls " .. abbrev(itemAmount("Trait Reroll")) }
                if S.gradeMsg then lines[#lines + 1] = S.gradeMsg end
                if S.traitMsg then lines[#lines + 1] = S.traitMsg end
                rerollStatus:SetText(table.concat(lines, "\n"))
            end)
            task.wait(0.1)
        end
    end)
end)

section("Towers", function()
    local TW = Tabs.Farm:AddLeftGroupbox(L["Auto Tower"], "swords")
    TW:AddDropdown("ad_tower", { Values = TOWER_LIST, Default = TOWER_LIST[1], Text = L["Tower"] })
    TW:AddToggle("ad_towerauto", { Text = L["Auto Tower"], Default = false, Tooltip = L["Plays the tower and restarts right away."] })
    TW:AddToggle("ad_towerteam", { Text = L["Auto Pick Best Team"], Default = true, Tooltip = L["Picks your strongest units before each run."] })
    TW:AddButton({ Text = L["Pick Best Team Now"], Func = function() fire("Towers", "EquipBestTowerTeam") end })
    local towerStatus = TW:AddLabel(L["Idle"], true)

    local refs = safeRequire(find(F, "Towers.TowerRefs")) or {}
    local actionWait = type(refs.ActionWaitTime) == "table" and refs.ActionWaitTime or { damagePlayer = 0.62, damageEnemy = 0.62, floorCompleted = 0.24, memberDefeated = 0.32, ended = 0, floorStarted = 0.76 }
    local startWait = type(refs.FloorStartedWaitTime) == "table" and refs.FloorStartedWaitTime or { initial = 0.76, transition = 0.38, repeated = 0 }
    local function sequenceTime(list)
        local total = 0
        for i, v in ipairs(list) do
            if v.action == "floorStarted" then
                local prev = list[i - 1]
                if i == 1 then
                    total = total + (v.floor == 1 and startWait.initial or startWait.transition)
                elseif prev and prev.action == "memberDefeated" then
                    total = total + startWait.transition
                else
                    total = total + startWait.repeated
                end
            else
                total = total + num(actionWait[v.action])
            end
        end
        return total
    end

    local T = { floor = 0, best = 0, runs = 0, state = L["Idle"], last = "" }
    local function teamSize()
        local d = data()
        local n = 0
        for _, v in pairs(d and type(d.TowerTeam) == "table" and d.TowerTeam or {}) do
            if v ~= nil and v ~= false and v ~= "" then n = n + 1 end
        end
        return n
    end
    local function itemSnapshot()
        local snap, unitCount = {}, 0
        local d = data()
        for key, e in pairs(d and type(d.Inventory) == "table" and d.Inventory or {}) do
            if type(e) == "table" then
                if unitEntries[e.name] then unitCount = unitCount + 1 else snap[key] = num(e.amount) end
            end
        end
        return snap, unitCount
    end
    local function dropSummary(before, beforeUnits)
        local after, afterUnits = itemSnapshot()
        local parts = {}
        for key, amt in pairs(after) do
            local diff = amt - (before[key] or 0)
            if diff > 0 then parts[#parts + 1] = clip(key, 14) .. " x" .. diff end
        end
        if afterUnits > beforeUnits then parts[#parts + 1] = (afterUnits - beforeUnits) .. L[" units"] end
        return #parts > 0 and table.concat(parts, ", ") or "no drops"
    end
    local function flushRun()
        invoke("Towers", "CancelTower")
        task.wait(0.4)
        for _ = 1, 3 do
            local res = invoke("Towers", "CompleteTowerFloor")
            if type(res) ~= "table" then break end
            task.wait(sequenceTime(res) + 0.05)
        end
    end
    onClean(function() task.spawn(flushRun) end)

    task.spawn(function()
        local failStreak = 0
        while RUNNING do
            if not on("ad_towerauto") then
                T.state = L["Idle"]
                task.wait(0.5)
            else
                if on("ad_towerteam") then fire("Towers", "EquipBestTowerTeam") task.wait(1.1) end
                local tower = Opt.ad_tower.Value
                T.state = "Starting"
                local before, beforeUnits = itemSnapshot()
                local started = invoke("Towers", "PlayTower", tower)
                if not started then
                    failStreak = failStreak + 1
                    if teamSize() == 0 then
                        T.state = "No team"
                        if failStreak == 1 then notify(L["Tower needs a team. Get some units first."]) end
                    else
                        T.state = "Retrying"
                        flushRun()
                    end
                    task.wait(3.1)
                else
                    failStreak = 0
                    T.runs = T.runs + 1
                    T.floor = 0
                    T.state = "Fighting"
                    local misses, ended = 0, false
                    while RUNNING and on("ad_towerauto") do
                        local res = invoke("Towers", "CompleteTowerFloor")
                        if type(res) == "table" then
                            misses = 0
                            for _, a in ipairs(res) do
                                if type(a) == "table" then
                                    if a.action == "floorStarted" and type(a.floor) == "number" then T.floor = a.floor end
                                    if a.action == "ended" then ended = true end
                                end
                            end
                            if T.floor > T.best then T.best = T.floor end
                            if ended then break end
                            task.wait(sequenceTime(res) + 0.05)
                        else
                            misses = misses + 1
                            if misses >= 8 then break end
                            task.wait(0.25)
                        end
                    end
                    if not ended then flushRun() end
                    T.last = string.format("Floor %d: %s", T.floor, dropSummary(before, beforeUnits))
                    notify(clip(tower, 18) .. L[" run over. "] .. T.last)
                    T.state = "Restarting"
                    task.wait(3.1)
                end
            end
        end
    end)
    task.spawn(function()
        while RUNNING do
            pcall(function()
                local lines = { string.format("%s  ·  Floor %d", T.state, T.floor), string.format("Best %d  ·  Runs %d  ·  Team %d", T.best, T.runs, teamSize()) }
                if T.last ~= "" then lines[#lines + 1] = clip(T.last, 30) end
                towerStatus:SetText(table.concat(lines, "\n"))
            end)
            task.wait(0.5)
        end
    end)
end)

section(L["Progress"], function()
    local function owned(d, name)
        local up = d and type(d.Upgrades) == "table" and d.Upgrades or {}
        return up[name] ~= nil and up[name] ~= false
    end
    local function nextUpgrade()
        local d = data()
        if not (d and M.Tree and M.Upgrades) then return nil end
        local cash = money()
        local best, bestPrice
        local queue, seen = { "Start" }, { Start = true }
        while #queue > 0 do
            local node = table.remove(queue, 1)
            local ok, kids = gcall(M.Tree.GetChildren, node)
            for _, child in ipairs(ok and type(kids) == "table" and kids or {}) do
                if not seen[child] then
                    seen[child] = true
                    if owned(d, child) then
                        queue[#queue + 1] = child
                    else
                        local info = M.Upgrades[child]
                        local price = info and num(info.price)
                        if price and price <= cash and S.canSpend(price) and (not bestPrice or price < bestPrice) then best, bestPrice = child, price end
                    end
                end
            end
        end
        return best
    end
    local function rebirthCost()
        local d = data()
        if not (d and M.Rebirths) then return nil end
        local ok, nxt = gcall(M.Rebirths.Get, num(d.Rebirth) + 1)
        return ok and type(nxt) == "table" and num(nxt.cost) or nil
    end

    local U = Tabs.Progress:AddLeftGroupbox(L["Upgrades"], "arrow-up")
    U:AddToggle("ad_upgrade", { Text = L["Auto Buy Upgrades"], Default = false, Tooltip = L["Buys the cheapest unlocked upgrade."] })
    local upStatus = U:AddLabel("-", true)

    local R = Tabs.Progress:AddLeftGroupbox("Rebirth", "refresh-cw")
    R:AddToggle("ad_rebirth", { Text = L["Auto Rebirth"], Default = false, Tooltip = L["Rebirths as soon as you can afford it."] })
    local rbStatus = R:AddLabel("-", true)

    local Q = Tabs.Progress:AddLeftGroupbox(L["Quests"], "ticket")
    Q:AddToggle("ad_quests", { Text = L["Auto Claim Quests"], Default = false })
    local shopNames = {}
    if M.Quests and type(M.Quests.Shop) == "table" then
        for _, it in ipairs(M.Quests.Shop) do
            if type(it) == "table" and type(it.name) == "string" and it.amount then shopNames[#shopNames + 1] = it.name end
        end
    end
    if #shopNames == 0 then shopNames = { "Gems", "Trait Reroll", "Lucky Spin" } end
    Q:AddDropdown("ad_ticketbuy", { Values = shopNames, Default = {}, Multi = true, AllowNull = true, Text = L["Spend Tickets On"] })
    Q:AddToggle("ad_tickets", { Text = L["Auto Spend Tickets"], Default = false })
    local qStatus = Q:AddLabel(L["Tickets: -"], true)

    local function claimQuests()
        local d = data()
        if not (d and type(d.Quests) == "table") then return end
        for _, period in ipairs({ "Daily", "Weekly" }) do
            local q = d.Quests[period]
            local cfg = M.Quests and M.Quests.Periods and M.Quests.Periods[period]
            if type(q) == "table" and cfg and type(cfg.quests) == "table" then
                local claimed = type(q.claimed) == "table" and q.claimed or {}
                local progress = type(q.progress) == "table" and q.progress or {}
                for _, quest in ipairs(cfg.quests) do
                    if not claimed[quest.id] and num(progress[quest.id]) >= num(quest.target) then
                        fire("QuestService", "Claim", period, quest.id, q.expiresAt)
                        task.wait(0.25)
                    end
                end
            end
        end
    end

    task.spawn(function()
        local t = { up = 0, rb = 0, q = 0, tk = 0 }
        while RUNNING do
            local now = os.clock()
            if on("ad_upgrade") and now - t.up > 0.5 then
                t.up = now
                local u = nextUpgrade()
                if u then fire(nil, "BuyUpgrade", u) end
            end
            if on("ad_rebirth") and now - t.rb > 0.6 then
                local cost = rebirthCost()
                if cost and money() >= cost then t.rb = now fire("RebirthService", "Rebirth") end
            end
            if on("ad_quests") and now - t.q > 15 then t.q = now pcall(claimQuests) end
            if on("ad_tickets") and now - t.tk > 2 then
                t.tk = now
                local set = multiSet("ad_ticketbuy")
                if set and itemAmount("Tickets") > 0 then
                    for name in pairs(set) do fire("QuestService", "Buy", name) end
                end
            end
            pcall(function()
                local d = data()
                local cost = rebirthCost()
                rbStatus:SetText(string.format(L["Rebirth %d"], d and num(d.Rebirth) or 0) .. (cost and (L["  ·  Next "] .. abbrev(cost)) or L["  ·  Max"]))
                local nu = nextUpgrade()
                upStatus:SetText(nu and (L["Next: "] .. nu) or L["Nothing affordable"])
                qStatus:SetText(L["Tickets: "] .. abbrev(itemAmount("Tickets")))
            end)
            task.wait(0.25)
        end
    end)
end)

section("Rewards", function()
    local function claimAll()
        fire("DailyRewardService", "Claim")
        fire("GroupRewardService", "Claim")
        fire("OfflineEarningsService", "Claim")
    end
    local function redeemAll()
        local d = data()
        local done = d and type(d.RedeemedCodes) == "table" and d.RedeemedCodes or {}
        local n = 0
        for _, c in ipairs(CODES) do
            if not done[c] then fire("CodesService", "RedeemCode", c) n = n + 1 task.wait(0.6) end
        end
        return n
    end
    local function useBoosts()
        local boosts = (type(M.Boosts) == "table" and type(M.Boosts.entries) == "table") and M.Boosts.entries or {}
        local d = data()
        local active = d and type(d.ActiveEntries) == "table" and d.ActiveEntries or {}
        for name in pairs(boosts) do
            if itemAmount(name) > 0 and not active[name] then fire("BoostService", "Use", name) task.wait(0.3) end
        end
    end

    local R = Tabs.Progress:AddRightGroupbox(L["Rewards & Codes"], "gift")
    R:AddToggle("ad_claim", { Text = L["Auto Claim Free Rewards"], Default = false, Tooltip = L["Daily, group and offline rewards."] })
    R:AddToggle("ad_boosts", { Text = L["Auto Use Boosts"], Default = false })
    R:AddButton({ Text = L["Claim All Now"], Func = function() claimAll() notify(L["Claimed what was available"]) end })

    R:AddDivider()
    local C = R
