    end })
    C:AddInput("ad_code", { Default = "", Numeric = false, Finished = false, ClearTextOnFocus = false, Text = L["Code"], Placeholder = L["Enter a code"] })
    C:AddButton({ Text = L["Redeem"], Func = function()
        local code = Opt.ad_code.Value
        if code ~= "" then fire("CodesService", "RedeemCode", code) notify(L["Sent"]) end
    end })

    task.spawn(function()
        local t = { c = -1e9, b = 0 }
        while RUNNING do
            local now = os.clock()
            if on("ad_claim") and now - t.c > 60 then t.c = now pcall(claimAll) end
            if on("ad_boosts") and now - t.b > 10 then t.b = now pcall(useBoosts) end
            task.wait(1)
        end
    end)
end)

section(L["Gear"], function()
    local gearCfg = safeRequire(find(F, "Inventory.Kinds.Gear.GearConfig"))
    local slots = (type(gearCfg) == "table" and type(gearCfg.slots) == "table") and gearCfg.slots or { "Head", "Torso", "Back", "Upper", "Waist" }
    local entries = (type(gearCfg) == "table" and type(gearCfg.entries) == "table") and gearCfg.entries or {}
    local FOCUS = { Cash = { "Money Multiplier" }, Luck = { "Luck" }, ["Tower Damage"] = { "Damage Multiplier", "Health Multiplier" } }
    local function buffValue(b)
        if type(b) ~= "table" then return 0 end
        local amt = num(b.amount)
        if b.bucket == "multiplier" then return amt - 1 end
        if b.bucket == "base" then return amt / 100 end
        return amt
    end
    local function score(name, focus)
        local cfg = entries[name]
        if type(cfg) ~= "table" then return -1 end
        local s = 0
        for _, key in ipairs(FOCUS[focus] or {}) do
            s = s + buffValue(type(cfg.buffs) == "table" and cfg.buffs[key] or nil) * 1000
        end
        return s + (RARITY_RANK[cfg.rarity or ""] or 0)
    end
    local function equipBestGear()
        local d = data()
        if not d then return 0 end
        local focus = Opt.ad_gearfocus and Opt.ad_gearfocus.Value or "Cash"
        local equipped = type(d.EquippedGear) == "table" and d.EquippedGear or {}
        local changed = 0
        for _, slot in ipairs(slots) do
            local best, bestScore
            for name, cfg in pairs(entries) do
                if type(cfg) == "table" and cfg.slot == slot and itemAmount(name) > 0 then
                    local sc = score(name, focus)
                    if not bestScore or sc > bestScore then best, bestScore = name, sc end
                end
            end
            if best and equipped[slot] ~= best then
                fire("GearService", "Equip", slot, best)
                changed = changed + 1
                task.wait(0.3)
            end
        end
        return changed
    end

    local G = Tabs.Progress:AddRightGroupbox(L["Gear"], "shield")
    G:AddDropdown("ad_gearfocus", { Values = { "Cash", "Luck", "Tower Damage" }, Default = "Cash", Text = L["Best Gear For"], Tooltip = L["Equips the gear that boosts this the most."] })
    G:AddToggle("ad_gear", { Text = L["Auto Equip Best Gear"], Default = false })
    local gearStatus = G:AddLabel("-", true)
    task.spawn(function()
        local last = 0
        while RUNNING do
            if on("ad_gear") and os.clock() - last > 5 then last = os.clock() pcall(equipBestGear) end
            pcall(function()
                local d = data()
                local n, owned = 0, 0
                for _ in pairs(d and type(d.EquippedGear) == "table" and d.EquippedGear or {}) do n = n + 1 end
                for name in pairs(entries) do if itemAmount(name) > 0 then owned = owned + 1 end end
                gearStatus:SetText(string.format(L["Equipped %d/%d  ·  Owned %d"], n, #slots, owned))
            end)
            task.wait(1)
        end
    end)
end)

