local function applyWS()
    if not on("ad_ws") then return end
    local h = hum()
    if h and h.WalkSpeed ~= Opt.ad_wsval.Value then h.WalkSpeed = Opt.ad_wsval.Value end
end
local wsConn
local function hookWS(char)
    if wsConn then wsConn:Disconnect() wsConn = nil end
    local h = char and char:WaitForChild("Humanoid", 10)
    if not h then return end
    wsConn = track(h:GetPropertyChangedSignal("WalkSpeed"):Connect(function() task.defer(applyWS) end))
    applyWS()
end
